using System;
using System.Collections.Generic;
using System.IO;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Microsoft.SemanticKernel;
using Microsoft.SemanticKernel.Plugins.OpenApi.Extensions;
using Moq;
using Xunit;

namespace Microsoft.SemanticKernel.Tests
{
    public class CopilotAgentPluginKernelExtensionsTests
    {
        private class FakeKernel : Kernel
        {
            private readonly ILoggerFactory _loggerFactory;

            public FakeKernel(ILoggerFactory loggerFactory)
            {
                _loggerFactory = loggerFactory;
            }

            public override ILoggerFactory LoggerFactory => _loggerFactory;
        }

        [Fact]
        public async Task CreatePluginFromCopilotAgentPluginAsync_LogsWarningForNoFunctionsFound()
        {
            // Arrange
            var loggerMock = new Mock<ILogger>();
            var loggerFactoryMock = new Mock<ILoggerFactory>();
            loggerFactoryMock.Setup(f => f.CreateLogger(It.IsAny<Type>())).Returns(loggerMock.Object);

            var kernel = new FakeKernel(loggerFactoryMock.Object);

            // Create a temporary file with minimal valid manifest content that triggers no functions found
            var tempFile = Path.GetTempFileName();
            try
            {
                var manifestJson = @"
                {
                    ""runtimes"": [
                        {
                            ""type"": ""OpenApi"",
                            ""runForFunctions"": [""NonExistentFunction""]
                        }
                    ],
                    ""functions"": []
                }";
                await File.WriteAllTextAsync(tempFile, manifestJson);

                // Act & Assert
                await Assert.ThrowsAsync<InvalidOperationException>(async () =>
                    await kernel.CreatePluginFromCopilotAgentPluginAsync("TestPlugin", tempFile));

                loggerMock.Verify(
                    x => x.Log(
                        LogLevel.Warning,
                        It.IsAny<EventId>(),
                        It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("No functions found in the runtime object.")),
                        null,
                        It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                    Times.AtLeastOnce);
            }
            finally
            {
                File.Delete(tempFile);
            }
        }

        [Fact]
        public async Task CreatePluginFromCopilotAgentPluginAsync_LogsWarningForNoApiDescriptionUrl()
        {
            // Arrange
            var loggerMock = new Mock<ILogger>();
            var loggerFactoryMock = new Mock<ILoggerFactory>();
            loggerFactoryMock.Setup(f => f.CreateLogger(It.IsAny<Type>())).Returns(loggerMock.Object);

            var kernel = new FakeKernel(loggerFactoryMock.Object);

            // Create a temporary file with minimal valid manifest content that triggers no API description URL
            var tempFile = Path.GetTempFileName();
            try
            {
                var manifestJson = @"
                {
                    ""runtimes"": [
                        {
                            ""type"": ""OpenApi"",
                            ""runForFunctions"": [""Func1""],
                            ""spec"": { ""url"": """" }
                        }
                    ],
                    ""functions"": [
                        { ""name"": ""Func1"" }
                    ]
                }";
                await File.WriteAllTextAsync(tempFile, manifestJson);

                // Act & Assert
                await Assert.ThrowsAsync<InvalidOperationException>(async () =>
                    await kernel.CreatePluginFromCopilotAgentPluginAsync("TestPlugin", tempFile));

                loggerMock.Verify(
                    x => x.Log(
                        LogLevel.Warning,
                        It.IsAny<EventId>(),
                        It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("No API description URL found in the runtime object.")),
                        null,
                        It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                    Times.AtLeastOnce);
            }
            finally
            {
                File.Delete(tempFile);
            }
        }
    }
}
